pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public {
        c = new C();
        c.initialize(); // test contract becomes owner
    }

    function testFuzz_property(bool pickZero, address candidate) public {
        // The fuzzer chooses whether the transfer targets the zero address;
        // otherwise an arbitrary fuzzed address is used.
        address newOwner = pickZero ? address(0) : candidate;

        bool ok;
        try c.transferOwnership(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: whenever ownership transfer succeeds, the owner is non-zero.
        // P: a transfer to address(0) reverts (ok == false) and ownership stays valid.
        // M: a transfer to address(0) succeeds (ok == true) and owner() == address(0).
        assertTrue(!ok || c.owner() != address(0));
    }
}

